		name: 'fx67llLoading',
		props: {
			// loader 类型，决定渲染哪种动效，可选值见文档「所有类型」
			type: {
				type: String,
				required: false,
				default: 'ball-pulse'
			},
			// loader 颜色，hex 格式，第一组经 currentColor 继承，第二组经 --loader-color 变量
			color: {
