			// loader 大小，支持 'sm'/'md'/'lg'/'xl'（第一组原生修饰类）或数字倍数
			size: {
				type: [String, Number],
				required: false,
				default: 'md'
			},
			// 单次动画时长（秒），null 时使用各款默认时长；通过 --loader-duration 注入
			duration: {
				type: Number,
				required: false,
				default: null,
				validator(num) {
					return num === null || (typeof num === 'number' && num > 0);
				}
