				}
			},
			// loading 下方提示文字
			tip: {
				type: String,
				required: false,
				default: ''
			},
			// 提示文字颜色，为空时跟随 color
			tipColor: {
				type: String,
				required: false,
				default: '',
				validator(color) {
					return color === '' || new RegExp(HEX_REG).test(color);
				}
			},
			// 延迟显示时间（毫秒），避免短请求闪烁，0 表示立即显示
			delay: {
				type: Number,
				required: false,
				default: 0,
				validator(num) {
					return typeof num === 'number' && num >= 0;
				}
			},
			// v-model 绑定值，控制组件显隐
			value: {
