		methods: {
			// 启动延迟显示逻辑：delay>0 时延迟后显示，否则立即显示
			startDelay() {
				this.clearDelay();
				if (this.delay > 0) {
					this.delayTimer = setTimeout(() => {
						this.showAfterDelay = true;
					}, this.delay);
				} else {
					this.showAfterDelay = true;
				}
			},
			// 清理 delay 定时器
			clearDelay() {
				if (this.delayTimer) {
					clearTimeout(this.delayTimer);
					this.delayTimer = null;
				}
			}
		}
	};
